WITH long_format AS (SELECT * FROM (SELECT id, category, cost, price FROM products) src UNPIVOT (value FOR metric IN (cost, price))) SELECT CASE WHEN value >= 89 THEN 'HIGH' ELSE 'LOW' END AS value_tier, ROUND(AVG(value), 2) AS avg_value, SUM(CASE WHEN metric = 'price' THEN value ELSE 0 END) AS price_value, COUNT_IF(category = 'Home') AS home_events, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT category) AS distinct_categories, SUM(CASE WHEN metric = 'cost' THEN value ELSE 0 END) AS cost_value FROM long_format GROUP BY value_tier ORDER BY value_tier DESC NULLS LAST;
